function BoundaryDemo() {
  return (
    <DemoSection
      chapter="01"
      docs={{
        href: "https://nextjs.org/docs/app/getting-started/server-and-client-components",
        label: "Server and Client Components",
      }}
      hook="Two components walk into a page."
      id="demo-01"
      intro={
        <>
          <p>
            Every component in the App Router runs on the server unless you say
            otherwise. One directive — <code>&quot;use client&quot;</code> —
            moves a subtree into the browser. Everything else follows from that
            split: what can read secrets, what can hold state, what ships
            JavaScript and what arrives as finished HTML.
          </p>
          <p>
            Both cards below are real. One rendered in Node.js and was cached
            into this page. The other hydrated in your tab and is waiting for
            you to click it.
          </p>
        </>
      }
      meta={
        <>
          The error that sends everyone here is &ldquo;useState only works in
          a Client Component&rdquo;. Now you know why: the server has no
          clicks to listen for.
        </>
      }
      sourcePath="apps/web/app/[locale]/(playground)/boundary"
      topic="server & client components"
    >
      <LivePanel
        label="two components, one page"
        readout="boundary drawn at the import graph · props cross it as serialized data"
